			public void LoadData()
			{
			Cursor.Current = Cursors.WaitCursor;
		
			var data = Kt.Db.Select<PatientRecordManagement.Models.Visit>();
			//-Filter daterange
data = data.Where(r => r.Date.Date >= dateStartDate.Value.Date).ToList();
data = data.Where(r => r.Date.Date <= dateEndDate.Value.Date).ToList();
//-filter Doctor
if (cmbFilterDoctorId.SelectedItem != null && cmbFilterDoctorId.SelectedItem.GetType() != typeof(string))
data = data.Where(r => r.DoctorId == ((PatientRecordManagement.Models.Doctor)cmbFilterDoctorId.SelectedItem).Id).ToList();
//filter
            if (_dataFilter != null)
                data = _dataFilter.Invoke(data).ToList();
			
			if (DataLimit > 0)
                data = data.Take(DataLimit).ToList();
			grid.Bind(data);
			Cursor.Current = Cursors.Default;
			}
