cmbFilterDoctorId.Items.Add("Doctor (All)");
cmbFilterDoctorId.Items.AddRange(cmbDoctorIdData.ToArray());
cmbFilterDoctorId.SelectedIndex = 0;
//fetch-filter
			Cursor.Current = Cursors.Default;
			}
